import java.io.*;
import java.util.*;

public class F {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split(" ");
        int n = Integer.parseInt(input[0]);
        int K = Integer.parseInt(input[1]);
        int L = Integer.parseInt(input[2]);
        int mod = 998244353;
        int[][] fif = enumFIF(10000, mod);
        long[] muls = new long[n + 1];
        for (int i = K; i <= n; i++) {
            long m = C(n, i, mod, fif);
            for (int j = i; j <= n; j++) {
                long sign = ((j - i) % 2 == 0) ? 1 : -1;
                muls[j] += m * C(n - i, n - j, mod, fif) * sign;
                muls[j] %= mod;
            }
        }
        long total = 0;
        for (int i = K; i <= n; i++) {
            long val = pow(2, i, mod) * fif[0][i] % mod * fif[0][i] % mod
                    * fif[1][2 * i + 1] % mod * muls[i];
            total += val;
            total %= mod;
        }
        if (total < 0) total += mod;
        System.out.println(total * L % mod);
    }

    public static long C(int n, int r, int mod, int[][] fif) {
        if (n < 0 || r < 0 || r > n) return 0;
        return (long) fif[0][n] * fif[1][r] % mod * fif[1][n - r] % mod;
    }

    public static long pow(long base, int exp, int mod) {
        long result = 1;
        long b = base % mod;
        for (int i = 0; i < exp; i++) {
            result = result * b % mod;
        }
        return result;
    }

    public static int[][] enumFIF(int n, int mod) {
        int[] fact = new int[n + 1];
        int[] invFact = new int[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (int) ((long) fact[i - 1] * i % mod);
        }
        long a = fact[n];
        long b = mod;
        long p = 1, q = 0;
        while (b > 0) {
            long c = a / b;
            long d = a;
            a = b;
            b = d % b;
            d = p;
            p = q;
            q = d - c * q;
        }
        invFact[n] = (int) (p < 0 ? p + mod : p);
        for (int i = n - 1; i >= 0; i--) {
            invFact[i] = (int) ((long) invFact[i + 1] * (i + 1) % mod);
        }
        return new int[][] { fact, invFact };
    }
}
